etColumnSearchPattern]('OperatorPersonnelGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @OperatorPersonnelGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OriginStationIATAGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @OriginStationIATAGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OwnerCompanyGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @OwnerCompanyGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PreviousStationIATAGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @PreviousStationIATAGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipperCompanyGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @ShipperCompanyGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShipToCompanyGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @ShipToCompanyGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Source1EquipmentGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @Source1EquipmentGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Source2EquipmentGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @Source2EquipmentGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('Source3EquipmentGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @Source3EquipmentGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('SupplierCompanyGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @SupplierCompanyGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('CarrierCompanyGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @CarrierCompanyGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ReasonCodeGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @ReasonCodeGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OriginStationIATAID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @OriginStationIATAID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('PreviousStationIATAID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @PreviousStationIATAID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('NextStationIATAID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @NextStationIATAID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('FinalStationIATAID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @FinalStationIATAID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('OperatorName'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @OperatorName END),@FuelAdditiveFlag,(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('IssuePoint'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @IssuePoint END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('IssuePointNumber'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @IssuePointNumber END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('RadioNumber'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @RadioNumber END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GateID'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @GateID END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('GateGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @GateGuid END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ShippingMethod'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @ShippingMethod END),(CASE (SELECT PATINDEX([sync].[udf_GetColumnSearchPattern]('ReferencedTransactionGuid'), @sync_supported_columns_tblTransactions)) WHEN 0 THEN NULL ELSE @ReferencedTransactionGuid END))
        ;
    
    SET @sync_row_count = @@rowcount;
    
    -- If we updated / inserted a record here, go ahead and remove any pending conflict records associated with this ID because this record should contain the most recent data.
    IF (@sync_row_count > 0)
    BEGIN
        SET NOCOUNT ON
        IF EXISTS (SELECT 1 FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @TransactionGuid) AND SyncConflictResolutionStatusIndex IN (0,3))
        BEGIN
            DELETE FROM [sync].[tblSyncRecordConflictToSyncSessionScopeLog] WHERE SyncRecordConflictGuid IN (SELECT SyncRecordConflictGuid FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @TransactionGuid))
            DELETE FROM [sync].[tblSyncRecordConflict] WHERE RecordKey = CONVERT(nvarchar(512), @TransactionGuid)
        END
        SET NOCOUNT OFF
    END    

    -- One issue with the MERGE approach is that we don't know if the @@rowcount is zero because of a true conflict now or if it was simply because
    -- the CreatedDate and UpdatedDate qualifiers were not met (in which case we want to simply throw away the update)
    -- In order to determine what took place, we're going to need to perform a query if @@rowcount = 0 to see if it was caused by the additional qualifiers.
    --
    IF (@sync_row_count = 0)
    BEGIN
        IF EXISTS (SELECT 1 FROM [dbo].[tblTransactions] WHERE TransactionGuid = @TransactionGuid AND (CreatedDate >= @CreatedDate OR UpdatedDate >= @UpdatedDate))
            SET @sync_row_count = 1;    
    END

    SET @minValidVersion = 0;   -- This is used to detect Change Tracking cleanup
                                -- If we support this, we should add a column to SynchronizationTable
                                -- that records the MinValidVersion after change tracking information for
                                -- a table gets cleaned up.  I don't think this will be necessary.
    
    IF @minValidVersion > @sync_last_received_anchor
        RAISERROR(N'(SI)Time between synchronization has exceeded the maximum amount of time for table ''%s'' (MIN: %I64d, LAST: %I64d).  To avoid data corruption and old data, the client must reinitialize its local database with a current refresh from the server.', 16, 3, @sync_table_name, @minValidVersion, @sync_last_received_anchor)
END

